---@field LoopViewRecord                	SuperScrollView.LoopGridView            
---@field BtnTabGroup2                  	UnityEngine.RectTransform               
---@field BtnTabGroup1                  	UnityEngine.RectTransform               
---@field TxtName                       	UnityEngine.RectTransform               
---@field ImgIconHead                   	UnityEngine.RectTransform               
local UIFeelingMessageRecordDialog = Class("UIFeelingMessageRecordDialog")

local STATE = {
    GET = 1,
    NO = 2,
}

function UIFeelingMessageRecordDialog:__init() 
    self._recordType = nil         --当前界面的类型
    self._catId = nil              --角色id
    self._catVo = nil
    self._unlockData = {}          --已解锁数据
    self._lockData = {}            --数据

    self._curState = 0
end

function UIFeelingMessageRecordDialog:__delete()
    self._recordType = nil         --当前界面的类型
    self._catId = nil              --角色id
    self._catVo = nil
    self._unlockData = {}          --已解锁数据
    self._lockData = {}            --数据

    self._curState = 0
end

function UIFeelingMessageRecordDialog:Awake()
    local argument = self.controller.Argument.parameters
    if not argument then
        return
    end
    self._catId = checkNumber(argument.catId)  

    --默认是短信
    if checkNumber(self._recordType) == 0 then
        self._recordType = Constants.PhoneTalkContentType.Message
    end

    self._catVo = PhoneUtils.GetCatVo(self._catId)
    if  not self._catVo then 
        return
    end

    self:RefeshSelf()
    SetButtonAction(self.bg, function()
        Events.Broadcast(Constants.EventNames.ChageChatPageState, {pageState = 1, catId = self._catId})
        UIModule.CloseDialog(self.controller)
        --UIModule.BackDialog()
    end)

    self:OnBtnTabGroupGet()
    KTool.SetActive(self.ImgTick, false)
    --CfUtils.FillText(self.Txtpossess, localize("未获得"))
    self._curState = STATE.GET

    SetButtonAction(self.ButChoose, function()
        if self._curState == STATE.GET then
            self._curState = STATE.NO
            KTool.SetActive(self.ImgTick, true)
            --self._recordType = Constants.PhoneTalkContentType.Telephone
        elseif self._curState == STATE.NO then
            self._curState = STATE.GET
            KTool.SetActive(self.ImgTick, false)
            --self._recordType = Constants.PhoneTalkContentType.Message
        end

        if self._recordType == Constants.PhoneTalkContentType.Message then
            self:OnBtnTabGroupGet()
        else
            self:OnBtnTabGroupNoHave()
        end
    end)
end

function UIFeelingMessageRecordDialog:RefeshSelf()
    --CfUtils.FillText(self.Text, localize("暂无历史聊天"))
    self:InitData()
    self:FillSelf()
end

function UIFeelingMessageRecordDialog:InitData()
    self._unlockData = {}          
    self._lockData = {}     
    local t = PhoneUtils.GetTalkContentIds(self._catId, self._recordType)
    if not t then
        return
    end 

    for k, v in pairs(t) do
        if checkNumber(v) ~= 0 then
            --解锁的
            if PhoneUtils.IsPassTalkContent(v) then
                table.insert(self._unlockData, v)
            else
                table.insert(self._lockData, v)
            end
        end
    end
    
    local t = clone(self._unlockData)
    for k, v in pairs(self._lockData) do
        table.insert(t, v)
    end
    self._lockData = t 
end

function UIFeelingMessageRecordDialog:FillSelf()
    KTool.SetActive(self.LoopViewRecord.gameObject, self._recordType == Constants.PhoneTalkContentType.Message)
    KTool.SetActive(self.LoopViewCall.gameObject, self._recordType ~= Constants.PhoneTalkContentType.Message)

    CfUtils.FillText(self.TxtName, self._catVo.name)
    local skinCardId = PhoneUtils.GetRoleCurCardSkinId(self._catId)
    CfUtils.FillImage(self.ImgIconHead, CardConfMgr:GetInstance():GetCardDefaultSmallHeadPath(skinCardId))

    CfUtils.FillText(self.BtnTabGroup1.transform:Find("Text"), localize("短信"))
    CfUtils.FillText(self.BtnTabGroup2.transform:Find("Text"), localize("语音"))

    SetButtonAction(self.BtnTabGroup1, Bind(self, self.OnBtnTabGroupGet))
    SetButtonAction(self.BtnTabGroup2, Bind(self, self.OnBtnTabGroupNoHave))
end

--短信
function UIFeelingMessageRecordDialog:OnBtnTabGroupGet()
    self._recordType = Constants.PhoneTalkContentType.Message
    self:RefeshSelf()

    KTool.SetActive(self.BtnTabGroup1.transform:Find("ImgLine"), self._recordType == Constants.PhoneTalkContentType.Message)
    KTool.SetActive(self.BtnTabGroup2.transform:Find("ImgLine"), self._recordType ~= Constants.PhoneTalkContentType.Message)

    local LoopView = (self._recordType == Constants.PhoneTalkContentType.Message and self.LoopViewRecord or self.LoopViewCall)
    local fun = (self._recordType == Constants.PhoneTalkContentType.Message and self.OnMessageCellByIndex or self.OnTelephoneCellByIndex)

    local t = {}
    if self._curState == STATE.NO then
        t = self._lockData
    else
        t = self._unlockData
    end
    KTool.SetActive(self.Empty, #t <= 0)

    if not self._isInitView then
        LoopView:InitGridView(#t, Bind(self, fun))
        self._isInitView = true
    else
        GameUtils.ReloadData(LoopView, #t)
    end
end

--手机
function UIFeelingMessageRecordDialog:OnBtnTabGroupNoHave()
    if true then
        GameUtils.Toast(localize("敬请期待"))
        return
    end

    self._recordType = Constants.PhoneTalkContentType.Telephone
    self:RefeshSelf()

    KTool.SetActive(self.BtnTabGroup1.transform:Find("ImgLine"), self._recordType == Constants.PhoneTalkContentType.Message)
    KTool.SetActive(self.BtnTabGroup2.transform:Find("ImgLine"), self._recordType ~= Constants.PhoneTalkContentType.Message)

    local LoopView = (self._recordType == Constants.PhoneTalkContentType.Message and self.LoopViewRecord or self.LoopViewCall)
    local fun = (self._recordType == Constants.PhoneTalkContentType.Message and self.OnMessageCellByIndex or self.OnTelephoneCellByIndex)

    local t = {}
    if self._curState == STATE.NO then
        t = self._lockData
    else
        t = self._unlockData
    end
    KTool.SetActive(self.Empty, #t <= 0)

    if not self._isInitView then
        LoopView:InitGridView(#t, Bind(self, fun))
        self._isInitView = true
    else
        GameUtils.ReloadData(LoopView, #t)
    end
end

function UIFeelingMessageRecordDialog:OnMessageCellByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local t = {}
    if self._curState == STATE.NO then
        t = self._lockData
    else
        t = self._unlockData
    end

    local id = t[index + 1]
    local cell = listView:NewListViewItem("itemcel")
    local scr = CfUtils.GetLuaScr(cell, UIFeelingMessageRecordTopicNode)
    if scr then
        scr:Refresh(id, function()
            if PhoneUtils.IsPassTalkContent(id) then
                Events.Broadcast(Constants.EventNames.ChageChatPageState, {pageState = 3, catId = self._catId, talkContentId = id, recordType = self._recordType})
                UIModule.CloseDialog(self.controller)
            else
                GameUtils.Toast(localize("该话题未解锁"))
            end
        end)
    end
    
    return cell
end

function UIFeelingMessageRecordDialog:OnTelephoneCellByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local t = {}
    if self._curState == STATE.NO then
        t = self._lockData
    else
        t = self._unlockData
    end

    local id = t[index + 1]
    local cell = listView:NewListViewItem("itemcel")
    local scr = CfUtils.GetLuaScr(cell, UIFeelingMessageRecordTopicNode)
    if scr then
        scr:Refresh(id, function()
            if self._curState == STATE.GET then
                UIModule.OpenDialog({ id = Constants.UITypeIds.UIFeelingCallDialog, parameters = {catId = self._catId, talkCountId = id}}, {
                })
            elseif self._curState == STATE.NO then
                GameUtils.Toast(localize("该话题未解锁"))
            else
                GameUtils.Toast(localize("需要先完成该话题才能回溯"))
            end
        end)
    end

    return cell
end

function UIFeelingMessageRecordDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CfUtils.SetTopCommonActive(false, false)
        CfUtils.SetUICameraProjection(true)
    end))
    return coWait
end

function UIFeelingMessageRecordDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CfUtils.SetTopCommonActive(true, false)
        CfUtils.SetUICameraProjection(false)
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIFeelingMessageRecordDialog
